describe('Username Availability Async Validation', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.get('[data-testid="username-input"]').as('usernameInput');
    cy.get('[data-testid="check-availability-btn"]').as('checkBtn');
    cy.get('[data-testid="availability-message"]').as('message');
  });

  it('should display available message when username is not taken', () => {
    cy.get('@usernameInput').type('newuser123');
    cy.get('@checkBtn').click();

    cy.get('@message', { timeout: 5000 })
      .should('be.visible')
      .and('contain', 'Username is available');

    cy.get('[data-testid="availability-status"]')
      .should('have.class', 'success');
  });

  it('should display unavailable message when username is already taken', () => {
    cy.get('@usernameInput').type('existinguser');
    cy.get('@checkBtn').click();

    cy.get('@message', { timeout: 5000 })
      .should('be.visible')
      .and('contain', 'Username is already taken');

    cy.get('[data-testid="availability-status"]')
      .should('have.class', 'error');
  });

  it('should handle validation for username with special characters', () => {
    cy.get('@usernameInput').type('user@#$%');
    cy.get('@checkBtn').click();

    cy.get('@message', { timeout: 5000 })
      .should('be.visible')
      .and('contain', 'Username contains invalid characters');

    cy.get('[data-testid="availability-status"]')
      .should('have.class', 'warning');
  });

  it('should show loading state during async validation', () => {
    cy.get('@usernameInput').type('testuser');
    cy.get('@checkBtn').click();

    cy.get('[data-testid="loading-spinner"]')
      .should('be.visible');

    cy.get('[data-testid="loading-spinner"]', { timeout: 5000 })
      .should('not.exist');

    cy.get('@message')
      .should('be.visible');
  });

  it('should handle empty username validation', () => {
    cy.get('@usernameInput').clear();
    cy.get('@checkBtn').click();

    cy.get('@message', { timeout: 5000 })
      .should('be.visible')
      .and('contain', 'Username cannot be empty');

    cy.get('[data-testid="availability-status"]')
      .should('have.class', 'error');
  });

  it('should handle network timeout gracefully', () => {
    cy.intercept('GET', '**/api/check-username*', (req) => {
      req.destroy();
    }).as('timeoutRequest');

    cy.get('@usernameInput').type('slowuser');
    cy.get('@checkBtn').click();

    cy.wait('@timeoutRequest');

    cy.get('@message', { timeout: 5000 })
      .should('be.visible')
      .and('contain', 'Unable to verify username availability');
  });
});
